            [("Orange area ↻ 8", "Oranger Bereich ↻ 8"), ("loop, the active one brighter, with its length in beats", "Loop, der aktive kräftiger, mit Länge in Beats")],
            [("Ticks, red ones", "Striche, rote"), ("beat grid, red at the start of a bar", "Beatgrid, rot am Taktanfang")],
            [("Green **SEND BPM**", "Grünes **SEND BPM**"), ("this deck gives the tempo to the light desk", "dieses Deck gibt das Tempo ans Lichtpult")],
